// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.prank(attacker);
        bool ok = false;
        try c.setRewardDistributor(attacker) { ok = true; }
        catch { ok = false; }
        assertTrue(!ok && c.rewardDistributor() != attacker);
    }
}
